<body>
<main class="wrap">
  <h1>Bevásárlólista</h1>
  <p class="hint">Írd be a terméket, válaszd ki a kategóriát, majd pipáld be, amit megvettél. A lista megmarad, ha bezárod az ablakot.</p>

  <form class="addbar" id="addForm">
    <label class="sr" for="newItem">Új termék neve</label>
    <input type="text" id="newItem" placeholder="pl. paradicsom" autocomplete="off" maxlength="60">
    <label class="sr" for="newCat">Kategória</label>
    <select id="newCat"></select>
    <button type="submit" class="btn-primary">Hozzáad</button>
  </form>

  <div class="summary" id="summary" hidden>
    <span class="count" id="count"></span>
    <div class="bar" aria-hidden="true"><i id="bar"></i></div>
    <button type="button" class="linkbtn" id="clearDone">Bevitt eltávolítása</button>
  </div>

  <div id="list"></div>
  <p class="sr" aria-live="polite" id="status"></p>
</main>

<script>
const CATEGORIES = [
  {key:'zoldsag', label:'Zöldség'},
  {key:'pekaru', label:'Pékáru'},
  {key:'tejtermek', label:'Tejtermék'},
  {key:'egyeb', label:'Egyéb'}
];
const KEY = 'shopping-list-v1';

const form = document.getElementById('addForm');
const nameInput = document.getElementById('newItem');
const catSelect = document.getElementById('newCat');
const listEl = document.getElementById('list');
const summaryEl = document.getElementById('summary');
const countEl = document.getElementById('count');
const barEl = document.getElementById('bar');
const clearDoneBtn = document.getElementById('clearDone');
const statusEl = document.getElementById('status');

let items = [];

CATEGORIES.forEach(c => {
  const o = document.createElement('option');
  o.value = c.key; o.textContent = c.label;
  catSelect.appendChild(o);
});

function catLabel(k){ const c = CATEGORIES.find(x => x.key === k); return c ? c.label : 'Egyéb'; }

async function load(){
  try{
    if(window.alfy && window.alfy.storage){
      const s = await window.alfy.storage.get(KEY);
      if(Array.isArray(s)) items = s;
    }
  }catch(e){ items = []; }
  render();
}
function save(){
  try{ if(window.alfy && window.alfy.storage) window.alfy.storage.set(KEY, items); }catch(e){}
}

function announce(msg){ statusEl.textContent = ''; setTimeout(() => statusEl.textContent = msg, 30); }

function render(){
  listEl.textContent = '';
  const total = items.length;
  const done = items.filter(i => i.done).length;

  if(total === 0){
    summaryEl.hidden = true;
    const e = document.createElement('div');
    e.className = 'empty';
    e.innerHTML = '<p class="big">Még nincs semmi a listán</p><p>Add hozzá az első terméket fent, és válaszd ki a kategóriáját.</p>';
    listEl.appendChild(e);
    return;
  }

  summaryEl.hidden = false;
  countEl.textContent = done + ' / ' + total + ' megvett';
  barEl.style.width = total ? (done / total * 100) + '%' : '0%';
  clearDoneBtn.disabled = done === 0;

  CATEGORIES.forEach(cat => {
    const group = items.filter(i => i.cat === cat.key);
    if(group.length === 0) return;
    const sec = document.createElement('section');
    sec.className = 'cat';

    const head = document.createElement('div');
    head.className = 'cat-head';
    const gDone = group.filter(i => i.done).length;
    head.innerHTML = '<span class="name"><span class="dot"></span><h2></h2></span>' +
      '<span class="cnt">' + gDone + ' / ' + group.length + '</span>';
    head.querySelector('h2').textContent = cat.label;
    sec.appendChild(head);

    const ul = document.createElement('ul');
    ul.className = 'items';
    group.forEach(item => {
      const li = document.createElement('li');
      li.className = 'item' + (item.done ? ' done' : '');
      const chk = document.createElement('input');
      chk.type = 'checkbox'; chk.className = 'chk'; chk.checked = !!item.done;
      chk.id = 'c' + item.id;
      chk.addEventListener('change', () => { item.done = chk.checked; save(); render(); });
      const lbl = document.createElement('label');
      lbl.htmlFor = chk.id; lbl.textContent = item.text;
      const del = document.createElement('button');
      del.type = 'button'; del.className = 'del'; del.textContent = '×';
      del.setAttribute('aria-label', 'Törlés: ' + item.text);
      del.addEventListener('click', () => { items = items.filter(x => x.id !== item.id); save(); render(); announce('Törölve: ' + item.text); });
      li.appendChild(chk); li.appendChild(lbl); li.appendChild(del);
      ul.appendChild(li);
    });
    sec.appendChild(ul);

    if(group.length > 1){
      const foot = document.createElement('div');
      foot.className = 'cat-foot';
      const b = document.createElement('button');
      b.type = 'button'; b.className = 'linkbtn'; b.textContent = 'Ez a kategória kiürítése';
      b.addEventListener('click', () => {
        items = items.filter(x => x.cat !== cat.key); save(); render();
        announce(cat.label + ' kategória kiürítve');
      });
      foot.appendChild(b);
      sec.appendChild(foot);
    }
    listEl.appendChild(sec);
  });
}

form.addEventListener('submit', (e) => {
  e.preventDefault();
  const text = nameInput.value.trim();
  if(!text){ nameInput.focus(); announce('Írd be a termék nevét'); return; }
  items.push({ id: Date.now() + '-' + Math.random().toString(36).slice(2, 7), text, cat: catSelect.value, done: false });
  save(); render();
  nameInput.value = '';
  nameInput.focus();
  announce('Hozzáadva: ' + text + ' (' + catLabel(catSelect.value) + ')');
});

clearDoneBtn.addEventListener('click', () => {
  const n = items.filter(i => i.done).length;
  items = items.filter(i => !i.done);
  save(); render();
  announce(n + ' bevitt termék eltávolítva');
});

load();
</script>
</body>
</html>
